-- 테스트 전용: models.py 와 migrations 주석을 근거로 재구성한 '마이그레이션 이전' 기본 스키마
CREATE TABLE tasks (task_id VARCHAR(30) PRIMARY KEY, block_id VARCHAR(30) NOT NULL, zone_id VARCHAR(30) NOT NULL,
  task_type VARCHAR(50) NOT NULL, status VARCHAR(30) NOT NULL, updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE voice_records (voice_id VARCHAR(50) PRIMARY KEY, worker_id VARCHAR(30), zone_id VARCHAR(30), block_id VARCHAR(30),
  task_id VARCHAR(30), transcript TEXT NOT NULL, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE event_categories (category_code VARCHAR(50) PRIMARY KEY, category_name VARCHAR(50) NOT NULL);
CREATE TABLE event_types (event_type VARCHAR(50) PRIMARY KEY, category_code VARCHAR(50) NOT NULL REFERENCES event_categories(category_code), description TEXT NOT NULL);
CREATE TABLE speech_types (speech_type VARCHAR(30) PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE events (event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, voice_id VARCHAR(50) NOT NULL UNIQUE REFERENCES voice_records(voice_id),
  task_id VARCHAR(30) REFERENCES tasks(task_id), event_type VARCHAR(50) NOT NULL, event_status VARCHAR(30) NOT NULL, summary TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
